Object.assign(translations.en, {kids:'Kids’ haircut (under 11)',kidsDesc:'Wash before and after, styling with products',peeling:'Scalp peeling',peelingDesc:'Scalp care treatment',styling:'Hair styling',stylingDesc:'Hair wash and styling'});
const config = window.BARBER_CONFIG;
const serviceDefinitions = [ ['haircut','haircut','haircutDesc'], ['kids','kids','kidsDesc'], ['beard','beardService','beardDesc'], ['combo','combo','comboDesc'], ['peeling','peeling','peelingDesc'], ['styling','styling','stylingDesc'] ];
let language = 'ru';
try { const saved = localStorage.getItem('ruslan-language'); if (translations[saved]) language = saved; } catch {}
const t = key => translations[language][key];
const emailEnabled = () => Object.values(config.emailjs).every(value => typeof value === 'string' && value.trim());
const form = document.querySelector('#booking-form');
const status = document.querySelector('#form-status');
const fallback = document.querySelector('#whatsapp-fallback');
const dateInput = form.elements.date;
const timeInput = form.elements.time;
const serviceSelect = form.elements.service;
const submit = form.querySelector('[type=submit]');
const calendar = new window.BookingCalendar({dateInput,timeInput,busySlots:config.busySlots,onChange:()=>{status.textContent='';fallback.hidden=true;refreshSummary();}});
const price = id => typeof config.prices[id] === 'number' && Number.isFinite(config.prices[id]) && config.prices[id] >= 0 ? `${new Intl.NumberFormat(language).format(config.prices[id])} AZN` : t('ask');

function renderServices() {
 const selected = serviceSelect.value;
 document.querySelector('#service-list').replaceChildren();
 serviceSelect.replaceChildren(new Option(t('choose'),''));
 serviceDefinitions.forEach(([id,name,description],index) => {
  const link=document.createElement('a');link.className='service-row';link.href='#booking';
  const number=document.createElement('span');number.className='service-number';number.textContent=`0${index+1}`;
  const content=document.createElement('div');const heading=document.createElement('h3');heading.textContent=t(name);const detail=document.createElement('p');detail.textContent=t(description);content.append(heading,detail);
  const amount=document.createElement('span');amount.className='price';amount.textContent=price(id);
  link.append(number,content,amount);link.addEventListener('click',()=>{serviceSelect.value=id;refreshSummary();});
  document.querySelector('#service-list').append(link);serviceSelect.add(new Option(`${t(name)} · ${price(id)}`,id));
 });
 serviceSelect.value=selected;
}
function setLanguage(next) {
 language=translations[next]?next:'ru';document.documentElement.lang=language;
 document.title=t('title');document.querySelector('meta[name=description]').content=t('description');document.querySelector('meta[property="og:title"]').content=t('title');document.querySelector('meta[property="og:description"]').content=t('description');
 document.querySelectorAll('[data-t]').forEach(el=>{el.textContent=t(el.dataset.t);});
 document.querySelectorAll('[data-aria]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.aria)));
 const altKeys={fade:'altFade',beard:'altBeard',tools:'altTools'};
 document.querySelectorAll('[data-alt]').forEach(el=>{el.alt=t(altKeys[el.dataset.alt]);});
 document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===language)));
 if(emailEnabled()){document.querySelector('#submit-label').textContent=t('emailSend');document.querySelector('#delivery-note').textContent=t('emailNote');}
 renderServices();calendar.setLanguage(language);refreshSummary();status.textContent='';fallback.hidden=true;
 try {localStorage.setItem('ruslan-language',language);} catch {}
}
function refreshSummary() {
 const definition=serviceDefinitions.find(s=>s[0]===serviceSelect.value);
 document.querySelector('#booking-summary').textContent=definition?`${t(definition[1])} · ${price(definition[0])}${dateInput.value?' · '+dateInput.value:''}${timeInput.value?' · '+timeInput.value+' (UTC+4)':''}`:'';
}
document.querySelectorAll('[data-lang]').forEach(button=>button.addEventListener('click',()=>setLanguage(button.dataset.lang)));
const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('.nav');
function closeMenu(){menu.setAttribute('aria-expanded','false');nav.classList.remove('is-open');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open);});
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
document.addEventListener('click',e=>{if(!nav.contains(e.target)&&!menu.contains(e.target))closeMenu();});
window.matchMedia('(min-width:761px)').addEventListener('change',closeMenu);
const lightbox=document.querySelector('.lightbox');
document.querySelectorAll('.gallery-card').forEach(card=>card.addEventListener('click',()=>{lightbox.querySelector('img').src=`assets/images/${card.dataset.image}`;lightbox.querySelector('img').alt=card.querySelector('img').alt;lightbox.querySelector('p').textContent=`${t(card.dataset.caption)} · ${t('stock')}`;lightbox.showModal();document.body.style.overflow='hidden';}));
lightbox.querySelector('button').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('close',()=>{document.body.style.overflow='';});
lightbox.addEventListener('click',e=>{if(e.target===lightbox){const r=lightbox.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)lightbox.close();}});
form.addEventListener('input',()=>{status.textContent='';fallback.hidden=true;form.elements.name.setCustomValidity('');form.elements.phone.setCustomValidity('');dateInput.setCustomValidity('');refreshSummary();});

form.addEventListener('submit',async event=>{
 event.preventDefault();
 const clientName=form.elements.name.value.trim();const clientPhone=form.elements.phone.value.trim();
 if(clientName.length<2){form.elements.name.setCustomValidity(t('invalidName'));form.reportValidity();return;}
 const digits=clientPhone.replace(/\D/g,'');if(digits.length<7||digits.length>15){form.elements.phone.setCustomValidity(t('invalidPhone'));form.reportValidity();return;}
 const calendarError=calendar.validate();
 if(calendarError){status.textContent=calendarError;return;}
 const definition=serviceDefinitions.find(s=>s[0]===serviceSelect.value);if(!definition)return;
 const bookingId=crypto.randomUUID?crypto.randomUUID():String(Date.now());
 const data={booking_id:bookingId,client_name:clientName,client_phone:clientPhone,service:`${t(definition[1])} · ${price(definition[0])}`,date:dateInput.value,time:timeInput.value,timezone:'Asia/Baku (UTC+4)',note:form.elements.note.value.trim(),language};
 const message=`${t('booking')}\n${t('request')}: ${bookingId}\n${t('name')}: ${clientName}\n${t('phone')}: ${clientPhone}\n${t('service')}: ${data.service}\n${t('date')}: ${data.date}\n${t('time')}: ${data.time} · ${data.timezone}\n${t('note')}: ${data.note||t('empty')}\n${t('pending')}`;
 const url=`https://wa.me/${config.phone}?text=${encodeURIComponent(message)}`;fallback.href=url;
 if(!emailEnabled()){
  status.textContent=t('prepared');fallback.hidden=false;
  window.open(url,'_blank','noopener,noreferrer');return;
 }
 submit.disabled=true;status.textContent=t('sending');document.querySelectorAll('[data-lang]').forEach(b=>b.disabled=true);
 try {
  const response=await fetch('https://api.emailjs.com/api/v1.0/email/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_id:config.emailjs.serviceId,template_id:config.emailjs.templateId,user_id:config.emailjs.publicKey,template_params:data}),signal:AbortSignal.timeout(15000)});
  if(!response.ok)throw new Error('Delivery failed');status.textContent=t('sent');
 }catch{status.textContent=t('failed');fallback.hidden=false;}
 finally{submit.disabled=false;document.querySelectorAll('[data-lang]').forEach(b=>b.disabled=false);}
});
document.querySelector('#year').textContent=new Date().getFullYear();setLanguage(language);
// Keep all content accessible when reduced motion is requested or observers are unavailable.
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
 const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target);}});},{threshold:0.08});
 document.querySelectorAll('.section-top,.gallery-card,.services-intro,.about-photo,.about-text,.booking-layout>div,.booking-form,.contact').forEach(el=>{el.classList.add('reveal');observer.observe(el);});
}
